// Renders the third-party license notice (app/public/third-party-licenses.html) from a list of packages.

/** Marks the file as generated by this script; About checks for it (app/src/logic/about.ts). */
export const MARKER = "<!-- siderea-third-party-licenses -->";

const escapeHtml = (text) =>
  text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

/**
 * @param {Array<{ name: string, version: string, license: string, homepage: string, text: string }>} packages
 * @param {string} [unavailable] why the list could not be generated (a placeholder page is written then)
 */
export function renderNotice(packages, unavailable) {
  // One section per distinct license text, so a license that thousands of crates share is printed once per copyright line.
  /** @type {Map<string, { license: string, text: string, users: Array<{ name: string, version: string, homepage: string }> }>} */
  const sections = new Map();
  for (const p of packages) {
    const text = p.text.trim();
    const key = `${p.license}\n${text}`;
    let section = sections.get(key);
    if (!section) {
      section = { license: p.license, text, users: [] };
      sections.set(key, section);
    }
    section.users.push({ name: p.name, version: p.version, homepage: p.homepage });
  }
  const ordered = [...sections.values()].sort((a, b) => a.license.localeCompare(b.license) || b.users.length - a.users.length);

  const body = unavailable
    ? `<p class="missing">The list of third-party licenses was not generated in this build (${escapeHtml(unavailable)}). ` +
      `Run <code>pnpm gen:licenses</code> in the folder app/ and rebuild.</p>`
    : ordered
        .map((section) => {
          const users = section.users
            .map((u) => `<li>${escapeHtml(u.name)} ${escapeHtml(u.version)}${u.homepage ? ` <span class="src">${escapeHtml(u.homepage)}</span>` : ""}</li>`)
            .join("");
          const text = section.text === "" ? "(The package ships no license file; see the license identifier above.)" : section.text;
          return `<section><h2>${escapeHtml(section.license)}</h2><ul>${users}</ul><pre>${escapeHtml(text)}</pre></section>`;
        })
        .join("\n");

  return `<!doctype html>
${MARKER}
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Siderea Planets — third-party licenses</title>
<style>
:root { color-scheme: dark; --bg: #1c1d21; --text: #e7e8eb; --muted: #9b9fa9; --line: #2e3036; --code: #101114; }
:root[data-theme="light"] { color-scheme: light; --bg: #f6f7f9; --text: #1a1c21; --muted: #5a606c; --line: #d8dce3; --code: #ffffff; }
@media (prefers-color-scheme: light) {
  :root:not([data-theme]) { color-scheme: light; --bg: #f6f7f9; --text: #1a1c21; --muted: #5a606c; --line: #d8dce3; --code: #ffffff; }
}
body { margin: 0; padding: 16px 20px 32px; background: var(--bg); color: var(--text); font: 16px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif; }
h1 { margin: 0 0 8px; font-size: 20px; }
h2 { margin: 28px 0 8px; padding-top: 16px; border-top: 1px solid var(--line); font-size: 17px; }
p, .src { color: var(--muted); }
ul { margin: 0 0 12px; padding-left: 20px; }
.src { font-size: 14px; overflow-wrap: anywhere; }
pre { margin: 0; padding: 12px; background: var(--code); border: 1px solid var(--line); border-radius: 6px; font: 15px/1.45 ui-monospace, "SF Mono", Menlo, Consolas, monospace; white-space: pre-wrap; overflow-wrap: anywhere; }
code { font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace; }
</style>
</head>
<body>
<h1>Third-party licenses</h1>
<p>Siderea Planets is free software under the GNU General Public License, version 3 or later. It contains the following components, each under its own license.</p>
${body}
</body>
</html>
`;
}
